<script setup lang="ts">
import { ref } from 'vue'
import { normalizeCrmSettings, type CrmSettings } from '../../utils/crm'
const props=defineProps<{value:CrmSettings;version:number;companyId:string}>(),emit=defineEmits<{saved:[];busy:[value:boolean]}>()
const form=ref<CrmSettings>(JSON.parse(JSON.stringify(props.value))),busy=ref(false),error=ref(''),notice=ref('')
const sources=ref(form.value.sources.join('\n')),tags=ref(form.value.tags.join('\n'))
const key=()=> 'item_'+Math.random().toString(36).slice(2,10)
async function save(){busy.value=true;emit('busy',true);error.value='';notice.value='';try{form.value.sources=sources.value.split('\n').map(s=>s.trim()).filter(Boolean);form.value.tags=tags.value.split('\n').map(s=>s.trim()).filter(Boolean);const settings=normalizeCrmSettings(form.value);await $fetch('/api/crm/settings',{method:'PUT',headers:{'x-company-id':props.companyId},body:{settings,version:props.version},retry:0});notice.value='CRM settings saved.';emit('saved')}catch(e:any){error.value=e?.data?.statusMessage||e.message}finally{busy.value=false;emit('busy',false)}}
</script>
<template><form class="space-y-6" @submit.prevent="save"><p v-if="error" role="alert" class="crm-error">{{error}}</p><p v-if="notice" role="status" class="crm-success">{{notice}}</p><fieldset :disabled="busy" class="space-y-6">
  <section class="crm-panel space-y-4"><div><h2 class="font-semibold">Sales pipelines</h2><p class="crm-help">Give each pipeline open stages and won/lost outcomes. Stages already used by deals must remain available.</p></div>
    <article v-for="(pipeline,index) in form.pipelines" :key="pipeline.key" class="space-y-3 rounded-lg border border-gray-200 p-3 dark:border-gray-700"><div class="flex flex-wrap gap-2"><label class="crm-label flex-1">Pipeline name<input v-model="pipeline.name" class="crm-input" required maxlength="100"/></label><button type="button" class="crm-button self-end" :disabled="form.pipelines.length===1" @click="form.pipelines.splice(index,1)">Remove pipeline</button></div>
      <div v-for="(stage,stageIndex) in pipeline.stages" :key="stage.key" class="grid items-end gap-2 sm:grid-cols-[1fr_100px_120px_auto]"><label class="crm-label">Stage name<input v-model="stage.name" class="crm-input" required maxlength="80"/></label><label class="crm-label">Probability %<input v-model.number="stage.probability" class="crm-input" type="number" min="0" max="100" :disabled="stage.status!=='OPEN'"/></label><label class="crm-label">Outcome<select v-model="stage.status" class="crm-input"><option value="OPEN">Open</option><option value="WON">Won</option><option value="LOST">Lost</option></select></label><div class="flex gap-1"><button type="button" class="crm-button" aria-label="Move stage earlier" :disabled="!stageIndex" @click="pipeline.stages.splice(stageIndex-1,0,pipeline.stages.splice(stageIndex,1)[0])">↑</button><button type="button" class="crm-button" @click="pipeline.stages.splice(stageIndex,1)">Remove</button></div></div>
      <button type="button" class="crm-button" @click="pipeline.stages.push({key:key(),name:'New stage',probability:25,status:'OPEN'})">Add stage</button>
    </article><button type="button" class="crm-button" @click="form.pipelines.push({key:key(),name:'New pipeline',stages:[{key:'new',name:'New',probability:10,status:'OPEN'},{key:'won',name:'Won',probability:100,status:'WON'},{key:'lost',name:'Lost',probability:0,status:'LOST'}]})">Add pipeline</button>
  </section>
  <section class="crm-panel grid gap-4 sm:grid-cols-2"><label class="crm-label">Lead sources, one per line<textarea v-model="sources" class="crm-input" rows="7" required/></label><label class="crm-label">Suggested tags, one per line<textarea v-model="tags" class="crm-input" rows="7"/></label></section>
  <section class="crm-panel space-y-4"><h2 class="font-semibold">Lead scoring</h2><p class="crm-help">Scores combine these signals and are capped at 100. They help prioritize follow-up.</p><div class="grid gap-3 sm:grid-cols-4"><label v-for="item in [['email','Has email'],['phone','Has phone'],['account','Business account linked'],['qualified','Qualified lead']]" :key="item[0]" class="crm-label">{{item[1]}}<input v-model.number="form.scoring[item[0] as keyof typeof form.scoring]" class="crm-input" type="number" min="0" max="100"/></label></div></section>
  <section class="crm-panel space-y-4"><h2 class="font-semibold">Follow-up automations</h2><div class="grid gap-4 sm:grid-cols-2"><label class="crm-label">New lead: create follow-up after (days)<input v-model.number="form.automations.newLeadFollowUpDays" class="crm-input" type="number" min="0" max="365"/></label><label class="crm-label">Won deal: create follow-up after (days)<input v-model.number="form.automations.wonFollowUpDays" class="crm-input" type="number" min="0" max="365"/></label></div><p class="crm-help">Set days to 0 to disable. Follow-ups become internal tasks assigned to the record owner.</p><label class="flex items-center gap-2 text-sm"><input v-model="form.automations.taskReminders" type="checkbox"/> Show internal alerts for tasks due within one hour or overdue</label></section>
  <section class="crm-panel space-y-3"><h2 class="font-semibold">Contact custom fields</h2><div v-for="(field,index) in form.customFields" :key="field.key" class="grid items-end gap-2 sm:grid-cols-4"><label class="crm-label">Field label<input v-model="field.label" class="crm-input" required/></label><label class="crm-label">Type<select v-model="field.type" class="crm-input"><option v-for="kind in ['TEXT','NUMBER','DATE','BOOLEAN']" :key="kind" :value="kind">{{kind}}</option></select></label><label class="flex items-center gap-2 py-2 text-sm"><input v-model="field.required" type="checkbox"/> Required</label><button type="button" class="crm-button" @click="form.customFields.splice(index,1)">Remove field</button></div><button type="button" class="crm-button" @click="form.customFields.push({key:key(),label:'New field',type:'TEXT',required:false})">Add custom field</button></section>
  <div class="flex justify-end"><UButton type="submit" :loading="busy">Save CRM settings</UButton></div>
</fieldset></form></template>
